"""Backend for JSON."""

import json
import sys

from wrc.codegen.cg import CGDocument, GenerationOptions
from wrc.codegen.cghtml import simple_md2html
from wrc.sema.ast import Guideline

REGULATIONS_ROOT = "https://www.worldcubeassociation.org/regulations/"
COMMENTS = (
    "Generated by `{cmd}` The WRC maintains this file as part "
    "of the Regulations repository. Every time we update this "
    "file, we have to remember to do a migration. See "
    "https://github.com/thewca/worldcubeassociation.org/pull/1650."
)


class WCADocumentJSON(CGDocument):
    """Implement a simple JSON generator from Regulations and Guidelines ASTs."""

    name = "JSON"

    def __init__(
        self,
        versionhash: str,
        language: str,
        pdf: str,
        generation_options: GenerationOptions,
    ):
        # We don't need it
        del language
        super().__init__(list, generation_options=generation_options)
        self.versionhash = versionhash
        self.urls = {
            "regulations": REGULATIONS_ROOT,
            "guidelines": REGULATIONS_ROOT + "guidelines.html",
            "pdf": pdf,
        }

    def visitWCAStates(self, states):
        self.state_lists = []
        retval = super().visitWCAStates(states)
        self.codegen = {
            "title": states.title,
            "version": states.version,
            "version_hash": self.versionhash,
            "text": states.text,
            "states_lists": self.state_lists,
            "comment": COMMENTS.format(cmd=" ".join(sys.argv)),
        }
        return retval

    def visitStatesList(self, states_list):
        self.current_states = []
        retval = super().visitStatesList(states_list)
        self.state_lists.append(
            {"title": states_list.title, "states": self.current_states}
        )
        return retval

    def emit(self, ast_reg, ast_guide):
        reg_list, guide_list = super().emit(ast_reg, ast_guide)
        if len(guide_list) > 0:
            reg_list.extend(guide_list)
        return json.dumps(reg_list, indent=2, separators=(",", ": ")), ""

    def visitRule(self, rule):
        label = None
        url = "/regulations/"

        if isinstance(rule, Guideline):
            url += "guidelines.html"
            label = rule.labelname

        url += "#" + rule.number
        reg_dict = {
            "class": "regulation",
            "id": rule.number,
            "content_html": simple_md2html(rule.text, self.urls),
            "url": url,
        }
        if label:
            reg_dict.update({"guideline_label": label})
        self.codegen.append(reg_dict)  # type: ignore # TODO
        retval = super().visitRule(rule)
        return retval

    def visitState(self, state):
        self.current_states.append(
            {
                "class": "state",
                "iso2": state.state_id,
                "continent_id": state.continent_id,
                "name": state.name,
                "info": state.info,
                "id": state.friendly_id,
            }
        )
        return True
